using System;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Net.Security;
using System.Security.Authentication;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Text;
using Microsoft.Win32.SafeHandles;

// Narrow, one-way transfer protocol.  JSON control frames are length-prefixed;
// the file itself is an exact byte stream after a successful ready response.
public static class RemoteFileTransferCore
{
    public const int MaxFileBytes = 16 * 1024 * 1024;
    public const long ReserveBytes = 64L * 1024 * 1024;
    const int MaxControlBytes = 16384;
    static readonly UTF8Encoding Utf8 = new UTF8Encoding(false, true);

    public static bool IsPrivateIPv4(string address) { IPAddress ip; if(!IPAddress.TryParse(address,out ip)||ip.AddressFamily!=AddressFamily.InterNetwork)return false;byte[] b=ip.GetAddressBytes();return b[0]==10||(b[0]==172&&b[1]>=16&&b[1]<=31)||(b[0]==192&&b[1]==168); }

    static byte[] ReadExactly(Stream s, int n) { byte[] b=new byte[n]; int p=0; while(p<n){int r=s.Read(b,p,n-p);if(r<=0)throw new EndOfStreamException();p+=r;} return b; }
    public static byte[] ReadFrame(Stream s) { byte[] h=ReadExactly(s,4); int n=(h[0]<<24)|(h[1]<<16)|(h[2]<<8)|h[3]; if(n<=0||n>MaxControlBytes)throw new InvalidDataException("invalid_frame"); return ReadExactly(s,n); }
    public static void WriteFrame(Stream s, string text) { byte[] b=Utf8.GetBytes(text); if(b.Length==0||b.Length>MaxControlBytes)throw new InvalidDataException("invalid_frame"); s.WriteByte((byte)(b.Length>>24));s.WriteByte((byte)(b.Length>>16));s.WriteByte((byte)(b.Length>>8));s.WriteByte((byte)b.Length);s.Write(b,0,b.Length);s.Flush(); }
    static bool FixedTimeEquals(byte[] x,byte[] y) { if(x==null||y==null||x.Length!=y.Length)return false;int diff=0;for(int i=0;i<x.Length;i++)diff|=x[i]^y[i];return diff==0; }
    public static bool FixedTokenEquals(string a,string b) { try { byte[] x=Convert.FromBase64String(a),y=Convert.FromBase64String(b); if(x.Length!=32||y.Length!=32)return false; return FixedTimeEquals(x,y); }catch{return false;} }
    public static bool IsSimpleName(string n) { if(n==null||n.Length==0||n.Length>96||!System.Text.RegularExpressions.Regex.IsMatch(n,"^[A-Za-z0-9][A-Za-z0-9._-]{0,95}$")||n=="."||n==".."||n.Contains("..")||n.EndsWith("."))return false;string b=n.Split('.')[0].ToUpperInvariant();return b!="CON"&&b!="PRN"&&b!="AUX"&&b!="NUL"&&!System.Text.RegularExpressions.Regex.IsMatch(b,"^(COM|LPT)[1-9]$"); }
    public static bool IsRegularExistingFile(string p) { try { var f=new FileInfo(p); return f.Exists && (f.Attributes & FileAttributes.ReparsePoint)==0 && (f.Attributes & FileAttributes.Directory)==0; }catch{return false;} }
    public static void RequireSafeDirectory(string root) { var d=new DirectoryInfo(root); if(!d.Exists || (d.Attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("unsafe_directory"); string full=Path.GetFullPath(root); if(!String.Equals(full.TrimEnd('\\'),root.TrimEnd('\\'),StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("directory_not_canonical"); for(var p=d;p!=null;){if((p.Attributes&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("reparse_ancestor");var next=p.Parent;if(next==null||String.Equals(next.FullName,p.FullName,StringComparison.OrdinalIgnoreCase))break;p=next;} }
    [System.Runtime.InteropServices.DllImport("kernel32.dll",CharSet=System.Runtime.InteropServices.CharSet.Unicode,SetLastError=true)] static extern SafeFileHandle CreateFile(string n,uint a,uint s,IntPtr x,uint d,uint f,IntPtr t);
    // Keep the inbox directory non-delete-shareable throughout write/commit.  This
    // blocks a same-session rename/delete of the directory while this Worker owns it.
    public static SafeFileHandle LockDirectoryAgainstDelete(string root) { var h=CreateFile(root,1,3,IntPtr.Zero,3,0x02000000,IntPtr.Zero);if(h==null||h.IsInvalid)throw new IOException("inbox_lock_failed");return h; }
    public static System.Collections.Generic.List<SafeFileHandle> LockAncestorDirectoriesAgainstDelete(string root) { RequireSafeDirectory(root);var list=new System.Collections.Generic.List<SafeFileHandle>();try{for(var d=new DirectoryInfo(root);d!=null;d=d.Parent)list.Add(LockDirectoryAgainstDelete(d.FullName));return list;}catch{foreach(var h in list)h.Dispose();throw;} }
    public static bool HasRequiredFreeSpace(long available,long size) { return size>=0&&size<=MaxFileBytes&&available>=size+ReserveBytes; }
    public static string HashFile(string p) { using(var s=File.OpenRead(p))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-",""); }
    public static bool CertificateMatches(X509Certificate c,string pin) { try { if(c==null||pin==null||pin.Length!=64)return false; using(var x=new X509Certificate2(c)){if(DateTime.UtcNow<x.NotBefore.ToUniversalTime()||DateTime.UtcNow>x.NotAfter.ToUniversalTime())return false; using(var h=SHA256.Create()){var b=h.ComputeHash(x.RawData); var exp=new byte[32];for(int i=0;i<32;i++)exp[i]=Convert.ToByte(pin.Substring(i*2,2),16);return FixedTimeEquals(b,exp);}}}catch{return false;} }
    static string Json(string id,bool ok,string code,string sha,long bytes){ return ok ? String.Format("{{\"version\":1,\"id\":\"{0}\",\"ok\":true,\"sha256\":\"{1}\",\"bytes\":{2}}}",id,sha,bytes) : String.Format("{{\"version\":1,\"id\":\"{0}\",\"ok\":false,\"error\":\"{1}\"}}",id,code); }
    // Header parser deliberately accepts only the fixed schema supplied by the PS wrapper.
    // Values are deliberately restricted to ASCII tokens/simple file names, so a
    // fixed regular expression is safer than a permissive generic JSON object model.
    static bool Header(string json,out string id,out string token,out string name,out long size,out string sha) { id=token=name=sha=null;size=-1; try { var m=System.Text.RegularExpressions.Regex.Match(json,"^\\{\\\"version\\\":1,\\\"id\\\":\\\"([0-9a-fA-F-]{36})\\\",\\\"token\\\":\\\"([A-Za-z0-9+/=]{1,128})\\\",\\\"operation\\\":\\\"put\\\",\\\"name\\\":\\\"([^\\\"\\\\/:]{1,96})\\\",\\\"size\\\":([0-9]{1,8}),\\\"sha256\\\":\\\"([0-9A-Fa-f]{64})\\\"\\}$",System.Text.RegularExpressions.RegexOptions.CultureInvariant); if(!m.Success)return false; id=m.Groups[1].Value;token=m.Groups[2].Value;name=m.Groups[3].Value;size=Int64.Parse(m.Groups[4].Value,System.Globalization.CultureInfo.InvariantCulture);sha=m.Groups[5].Value; Guid g; return Guid.TryParseExact(id,"D",out g)&&IsSimpleName(name)&&size>=0&&size<=MaxFileBytes; }catch{return false;} }
    static bool IsReady(string text,string id) { return text==String.Format("{{\"version\":1,\"id\":\"{0}\",\"ok\":true,\"sha256\":\"\",\"bytes\":0}}",id); }
    static bool IsFinal(string text,string id,string sha,long size) { return text==Json(id,true,"complete",sha,size); }
    static bool IsBoundedError(string text,string id) { return System.Text.RegularExpressions.Regex.IsMatch(text,"^\\{\\\"version\\\":1,\\\"id\\\":\\\""+System.Text.RegularExpressions.Regex.Escape(id)+"\\\",\\\"ok\\\":false,\\\"error\\\":\\\"(unauthorized|destination_exists|insufficient_space|partial_exists|sha256_mismatch)\\\"\\}$"); }
    public static void ServeOne(TcpClient tcp,X509Certificate2 cert,string expectedRemote,string token,string inbox) {
        string temp=null,id="00000000-0000-0000-0000-000000000000"; bool owned=false; System.Collections.Generic.List<SafeFileHandle> locks=null;
        try { if(!String.Equals(((IPEndPoint)tcp.Client.RemoteEndPoint).Address.ToString(),expectedRemote,StringComparison.Ordinal)||DateTime.UtcNow<cert.NotBefore.ToUniversalTime()||DateTime.UtcNow>cert.NotAfter.ToUniversalTime())return; tcp.ReceiveTimeout=60000;tcp.SendTimeout=15000;using(tcp)using(var ssl=new SslStream(tcp.GetStream(),false)){ssl.ReadTimeout=60000;ssl.WriteTimeout=15000;IAsyncResult auth=ssl.BeginAuthenticateAsServer(cert,false,SslProtocols.Tls12,false,null,null);try{if(!auth.AsyncWaitHandle.WaitOne(10000))throw new TimeoutException("tls_timeout");ssl.EndAuthenticateAsServer(auth);}finally{auth.AsyncWaitHandle.Close();} string got,n,sha,hdr=Utf8.GetString(ReadFrame(ssl));long size;if(!Header(hdr,out id,out got,out n,out size,out sha)||!FixedTokenEquals(got,token)){WriteFrame(ssl,Json(id,false,"unauthorized",null,0));return;}locks=LockAncestorDirectoriesAgainstDelete(inbox);RequireSafeDirectory(inbox);string final=Path.Combine(inbox,n);if(!String.Equals(Path.GetDirectoryName(final),Path.GetFullPath(inbox).TrimEnd('\\'),StringComparison.OrdinalIgnoreCase)||File.Exists(final)||Directory.Exists(final)){WriteFrame(ssl,Json(id,false,"destination_exists",null,0));return;}if(!HasRequiredFreeSpace(new DriveInfo(Path.GetPathRoot(inbox)).AvailableFreeSpace,size)){WriteFrame(ssl,Json(id,false,"insufficient_space",null,0));return;}temp=Path.Combine(inbox,".incoming-"+id+".part");if(File.Exists(temp)){WriteFrame(ssl,Json(id,false,"partial_exists",null,0));return;}WriteFrame(ssl,Json(id,true,"ready","",0));string actual;using(var fs=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None,81920,FileOptions.WriteThrough)){owned=true;using(var h=SHA256.Create()){long left=size;byte[] b=new byte[81920];while(left>0){int r=ssl.Read(b,0,(int)Math.Min(b.Length,left));if(r<=0)throw new EndOfStreamException();fs.Write(b,0,r);h.TransformBlock(b,0,r,null,0);left-=r;}h.TransformFinalBlock(new byte[0],0,0);actual=BitConverter.ToString(h.Hash).Replace("-","");}fs.Flush(true);}if(!String.Equals(actual,sha,StringComparison.OrdinalIgnoreCase)){File.Delete(temp);owned=false;WriteFrame(ssl,Json(id,false,"sha256_mismatch",null,0));return;}File.Move(temp,final);owned=false;WriteFrame(ssl,Json(id,true,"complete",actual,size));}}catch{}finally{if(owned&&locks!=null){try{RequireSafeDirectory(inbox);if(File.Exists(temp))File.Delete(temp);}catch{}}if(locks!=null)foreach(var h in locks)h.Dispose();if(tcp!=null)tcp.Close();}
    }
    public static string Send(string address,int port,string pin,string token,string source,string name) {
        IPAddress parsed;if(!IPAddress.TryParse(address,out parsed)||(!IsPrivateIPv4(address)&&!IPAddress.IsLoopback(parsed))||!IsRegularExistingFile(source)||!IsSimpleName(name)||port<1||port>65535)throw new ArgumentException("invalid_transfer_input");string sourceRoot=Path.GetDirectoryName(Path.GetFullPath(source));var locks=LockAncestorDirectoriesAgainstDelete(sourceRoot);try{RequireSafeDirectory(sourceRoot);if(!IsRegularExistingFile(source))throw new InvalidDataException("source_changed");using(var fs=new FileStream(source,FileMode.Open,FileAccess.Read,FileShare.Read)){long size=fs.Length;if(size>MaxFileBytes)throw new InvalidDataException("file_too_large");string sha;using(var h=SHA256.Create()){sha=BitConverter.ToString(h.ComputeHash(fs)).Replace("-","");}fs.Position=0;string id=Guid.NewGuid().ToString("D"),header=String.Format("{{\"version\":1,\"id\":\"{0}\",\"token\":\"{1}\",\"operation\":\"put\",\"name\":\"{2}\",\"size\":{3},\"sha256\":\"{4}\"}}",id,token,name,size,sha);using(var tcp=new TcpClient(AddressFamily.InterNetwork)){IAsyncResult c=tcp.BeginConnect(address,port,null,null);try{if(!c.AsyncWaitHandle.WaitOne(10000))throw new TimeoutException("connect_timeout");tcp.EndConnect(c);}finally{c.AsyncWaitHandle.Close();}tcp.ReceiveTimeout=60000;tcp.SendTimeout=15000;using(var ssl=new SslStream(tcp.GetStream(),false,(s,x,ch,e)=>CertificateMatches(x,pin))){ssl.ReadTimeout=60000;ssl.WriteTimeout=15000;IAsyncResult a=ssl.BeginAuthenticateAsClient("PiRemoteFileTransfer",null,SslProtocols.Tls12,false,null,null);try{if(!a.AsyncWaitHandle.WaitOne(10000))throw new TimeoutException("tls_timeout");ssl.EndAuthenticateAsClient(a);}finally{a.AsyncWaitHandle.Close();}WriteFrame(ssl,header);string ready=Utf8.GetString(ReadFrame(ssl));if(!IsReady(ready,id)){if(IsBoundedError(ready,id))return ready;throw new InvalidDataException("unknown_result_no_retry");}byte[] b=new byte[81920];long left=size;while(left>0){int n=fs.Read(b,0,(int)Math.Min(b.Length,left));if(n<=0)throw new EndOfStreamException("source_changed");ssl.Write(b,0,n);left-=n;}ssl.Flush();string final=Utf8.GetString(ReadFrame(ssl));if(IsFinal(final,id,sha,size))return final;if(IsBoundedError(final,id))return final;throw new InvalidDataException("unknown_result_no_retry");}}}}finally{foreach(var h in locks)h.Dispose();} }
}
